const upsertProfile = `-- name: UpsertProfile :one
insert into public_profiles (
  user_id,
  handle,
  display_name
) values (
  $1, $2, $3
)
on conflict (user_id) do update set
  handle = excluded.handle,
  display_name = excluded.display_name,
  update_time = now()
returning user_id, handle, display_name
`

type UpsertProfileParams struct {
	UserID      pgtype.UUID
	Handle      string
	DisplayName string
}

type UpsertProfileRow struct {
	UserID      pgtype.UUID
	Handle      string
	DisplayName string
}

func (q *Queries) UpsertProfile(ctx context.Context, arg *UpsertProfileParams) (*UpsertProfileRow, error) {
	row := q.db.QueryRow(ctx, upsertProfile, arg.UserID, arg.Handle, arg.DisplayName)
	var i UpsertProfileRow
	err := row.Scan(&i.UserID, &i.Handle, &i.DisplayName)
	return &i, err
}
